<script setup lang="ts">
import { computed,ref,watch,nextTick } from 'vue'
import { renderMarkdown } from '../markdown'
import ArticleBody from '../reading/ArticleBody.vue'
import { fieldDisplay } from './types'
import PhotoGallery from '../life/PhotoGallery.vue'
import PlaceMap from '../life/PlaceMap.vue'
import TripView from '../life/TripView.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
const props=defineProps<{article:any;config:any}>()
const emit=defineEmits<{(e:'navigate',path:string):void}>()
const modules=computed(()=>props.config.modules.filter((m:any)=>m.enabled))
function fields(m:any){return props.article.fields.filter((f:any)=>m.field_ids.includes(f.id)&&fieldDisplay(f,props.article.values[f.id]))}
function timeline(m:any){return fields(m).filter((f:any)=>f.kind==='date').sort((a:any,b:any)=>String(props.article.values[a.id]).localeCompare(String(props.article.values[b.id])))}
// Keep removed/hidden values discoverable after an explicit version upgrade.
const retained=computed(()=>{const visible=new Set(modules.value.filter((m:any)=>['summary','fields','timeline'].includes(m.kind)).flatMap((m:any)=>m.field_ids));return props.article.fields.filter((f:any)=>!visible.has(f.id)&&fieldDisplay(f,props.article.values[f.id]))})
const selectedPlace=ref<string|null>(null)
const linkedTimeline=computed(()=>[...new Map(props.article.links.map((r:any)=>[r.id,r])).values()].sort((a:any,b:any)=>String(a.display_date).localeCompare(String(b.display_date))) as any[])
const photo=ref<any>(null),dialog=ref<HTMLDialogElement|null>(null)
watch(photo,async p=>{if(p){await nextTick();dialog.value?.showModal()}else dialog.value?.close()})
</script>
<template><div class="template-renderer">
<section v-for="m in modules" :key="m.id" class="template-module" :class="['template-'+m.kind,'variant-'+m.layout]" :data-module="m.kind">
<template v-if="m.kind==='header'"><header class="article-heading"><span class="blog-kicker">{{article.type_name}} · {{article.display_date}}</span><h1>{{article.title}}</h1></header><figure v-if="article.cover" class="article-cover"><button class="photo-button" aria-label="放大封面图片" @click="photo=article.media.find((p:any)=>p.id===article.cover.id)"><PrivatePreview variant="preview" :eager="true" :id="article.cover.id" :alt="article.cover.alt" :width="article.cover.width" :height="article.cover.height" /></button></figure></template>
<template v-else-if="m.kind==='body'"><h2 v-if="m.title">{{m.title}}</h2><ArticleBody :source="article.body" :format="article.body_format" :namespace="'post-'+article.id+'-'+m.id" /></template>
<template v-else-if="m.kind==='summary'||m.kind==='fields'"><details v-if="m.kind==='summary'&&fields(m).length"><summary>{{m.title||'记录信息（可选）'}}</summary><dl class="template-cards"><div v-for="f in fields(m)" :key="f.id"><dt>{{f.name}}</dt><dd>{{fieldDisplay(f,article.values[f.id])}}</dd></div></dl></details><template v-if="m.kind==='fields'"><h2 v-if="m.title">{{m.title}}</h2><dl class="template-cards"><div v-for="f in fields(m)" :key="f.id"><dt>{{f.name}}</dt><dd v-if="f.kind==='markdown'" class="blog-prose" v-html="renderMarkdown(String(article.values[f.id]))"></dd><dd v-else :class="{'template-date':f.kind==='date'}">{{fieldDisplay(f,article.values[f.id])}}</dd></div></dl></template></template>
<template v-else-if="(m.kind==='gallery'||m.kind==='album')&&article.media.length"><h2>{{m.title||'影像片刻'}}</h2><PhotoGallery :photos="article.media" :notes="article.life?.photos" :places="article.places" :layout="m.layout" :group-by="m.group_by||'none'" /></template>
<template v-else-if="m.kind==='itinerary'&&article.article?.travel_enabled!==false"><details><summary>{{m.title||'行程整理与历史活动'}}</summary><TripView :article="article" :selected="selectedPlace" @select="selectedPlace=$event" /></details></template>
<template v-else-if="m.kind==='map'&&article.article?.travel_enabled!==false"><h2>{{m.title||'故事里的地点'}}</h2><PlaceMap :article="article" :selected="selectedPlace" @select="selectedPlace=$event" /></template>
<template v-else-if="m.kind==='life_timeline'"><h2>{{m.title||'关联生活时间线'}}</h2><ol class="template-timeline"><li v-for="r in linkedTimeline" :key="r.id"><time>{{r.display_date}}</time><a :href="'/posts/'+r.id" @click.prevent="emit('navigate','/posts/'+r.id)">{{r.title}} ↗</a></li></ol><a href="/timeline" @click.prevent="emit('navigate','/timeline')">浏览全部生活时间线 ↗</a></template>
<template v-else-if="m.kind==='timeline'"><details><summary>日期信息</summary><h2 v-if="m.title">{{m.title}}</h2><ol class="template-timeline"><li v-for="f in timeline(m)" :key="f.id"><time>{{article.values[f.id]}}</time><strong>{{f.name}}</strong></li></ol></details></template>
<template v-else-if="m.kind==='related'"><section v-if="article.links.length" class="related-stories"><h2>{{m.title||'关联故事'}}</h2><a v-for="r in article.links" :key="r.id+r.label" :href="'/posts/'+r.id" @click.prevent="emit('navigate','/posts/'+r.id)"><span>{{r.label}}</span><strong>{{r.title}} ↗</strong></a></section><section v-if="article.places.length" class="reading-places"><h2>故事中的地点</h2><div v-for="p in article.places" :key="p.id"><h3>{{p.name}}</h3><p>{{[p.country,p.region,p.city,p.address].filter(Boolean).join(' · ')}}</p><p class="plain-value">{{p.notes}}</p></div></section></template>
</section>
<details v-if="retained.length" class="template-retained"><summary>其他已保存字段（{{retained.length}}）</summary><dl class="reading-fields"><div v-for="f in retained" :key="f.id"><dt>{{f.name}}</dt><dd v-if="f.kind==='markdown'" class="blog-prose" v-html="renderMarkdown(String(article.values[f.id]))"></dd><dd v-else>{{fieldDisplay(f,article.values[f.id])}}</dd></div></dl></details>
<dialog ref="dialog" class="lightbox" aria-label="图片放大预览" @close="photo=null" @click="($event.target===dialog)&&(photo=null)"><template v-if="photo"><button class="lightbox-close" autofocus @click="photo=null">关闭图片</button><PrivatePreview variant="preview" :eager="true" :id="photo.id" :alt="photo.alt" /><p>{{photo.caption||photo.title}}</p></template></dialog>
</div></template>
<style scoped>
.template-module{margin:0 0 42px;overflow-wrap:anywhere}.template-module h2{font-size:clamp(24px,3vw,34px)}.template-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:18px;margin:20px 0}.template-cards>div{background:var(--reader-card-background,var(--surface));border:1px solid var(--reader-border,var(--line));border-radius:var(--radius);padding:22px;box-shadow:var(--shadow);min-width:0}.template-cards dt{color:var(--reader-muted-text,var(--muted));font-size:13px}.template-cards dd{margin:12px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:19px}.template-cards .blog-prose{font-size:17px}.variant-date .template-date{font-family:var(--heading);font-size:clamp(24px,4vw,38px);color:var(--reader-accent,var(--accent))}.template-photos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.template-photos figure{margin:0;break-inside:avoid}.template-photos img{width:100%;display:block;aspect-ratio:1.3;object-fit:cover;border-radius:var(--radius)}.template-photos figcaption{font-size:14px;color:var(--reader-muted-text,var(--muted));padding:10px 0}.variant-masonry .template-photos{display:block;columns:2;column-gap:20px}.variant-masonry figure{margin-bottom:20px}.variant-masonry img{aspect-ratio:auto;height:auto}.variant-large .template-photos{grid-template-columns:1fr}.variant-large img{aspect-ratio:auto;max-height:900px;object-fit:contain}.template-timeline{padding-left:24px;list-style:none;border-left:2px solid var(--reader-border,var(--line));margin:26px 0 26px 10px}.template-timeline li{position:relative;padding:10px 0 25px 10px;display:grid;gap:8px}.template-timeline li:before{content:'';position:absolute;width:12px;height:12px;left:-31px;top:18px;background:var(--reader-accent,var(--accent));border-radius:50%}.template-timeline time{color:var(--reader-accent,var(--accent));font-size:18px}.template-retained{padding:22px;border:1px dashed var(--reader-border,var(--line));border-radius:var(--radius)}.template-retained summary{cursor:pointer;min-height:44px}
@media(max-width:600px){.template-photos{grid-template-columns:1fr}.variant-masonry .template-photos{columns:1}.template-cards>div{padding:18px}.template-module{margin-bottom:30px}}
</style>
